START TRANSACTION;
DELETE x FROM collection_dpd x JOIN collection_period p ON x.period_id=p.period_id WHERE p.grain_id=2 AND p.period_date IN ('2026-06-16','2026-06-17','2026-06-18');
DELETE x FROM collection_npa x JOIN collection_period p ON x.period_id=p.period_id WHERE p.grain_id=2 AND p.period_date IN ('2026-06-16','2026-06-17','2026-06-18');
DELETE FROM collection_period WHERE grain_id=2 AND period_date IN ('2026-06-16','2026-06-17','2026-06-18');
DELETE x FROM portfolio_pos x JOIN portfolio_period p ON x.portfolio_id=p.portfolio_id WHERE p.period_month IN ('2025-04-01','2025-05-01','2025-06-01') AND p.created_by='pg_migration';
DELETE FROM portfolio_period WHERE period_month IN ('2025-04-01','2025-05-01','2025-06-01') AND created_by='pg_migration';
COMMIT;
